-- Host fragment: the DELL — bare Hyprland, no DMS.
-- Loaded by hyprland.lua only when HOST == "dell", and only after its hand-owned
-- input block, so the per-device rows here land last and win.
--
-- Why this file exists: on homepc every one of these values is contributed by a
-- DMS-generated fragment (dms/colors, dms/layout, dms/cursor, dms/input, dms/binds)
-- that is both regenerated by DMS and gitignored — so on the dell those files do
-- not exist at all, and the unguarded requires used to take the whole config down.
-- The values below are ported from the pre-Lua baseline that used to cover both
-- hosts: ~/.config/hypr/legacy/hyprland.conf (shared) + legacy/dell.conf (this
-- host). Both have been inert since Hyprland 0.55 started loading hyprland.lua
-- instead of hyprland.conf — i.e. this is the config the dell last actually ran.
--
-- Validate without sitting at the laptop:  HYPR_HOST=dell Hyprland --verify-config

-- ─── Cursor ────────────────────────────────────────────────────────────────
-- apple-cursor (users.users.javi.packages in common.nix) ships XCursor only, no
-- hyprcursor theme, so XCURSOR_* is the only mechanism that resolves here.
-- Same pair the greeter sets in ~/.config/nixos/dell/… and legacy/hyprland.conf had.
hl.env("XCURSOR_THEME", "macOS")
hl.env("XCURSOR_SIZE", "24")

-- ─── Monitors ──────────────────────────────────────────────────────────────
-- legacy/dell.conf: `monitor=eDP-1,preferred,0x0,1`. This is the only durable
-- monitor config the dell has (dms/outputs.lua is homepc's, and it is host-guarded
-- in hyprland.lua). Docked panels: add a hl.monitor per output, or leave it to
-- Hyprland's defaults.
hl.monitor({ output = "eDP-1", mode = "preferred", position = "0x0", scale = 1 })
-- legacy/dell.conf also carried, commented:  monitor=DP-1,preferred,0x0,1.5

-- ─── Border colors ─────────────────────────────────────────────────
-- homepc gets these from DMS's matugen hook; the dell has no matugen, so the
-- pre-Lua gradient border is kept (legacy/hyprland.conf had
-- `col.active_border = rgba(556677dd) rgba(445566dd) 45deg`). A multi-stop border
-- is NOT a string in the Lua API: HL.Gradient = `string | {colors = {...}, angle = n}`.
-- The hyprlang string form is rejected ("invalid color") — caught by --verify-config.
hl.config({
    general = {
        col = {
            active_border = {
                colors = { "rgba(556677dd)", "rgba(445566dd)" },
                angle    = 45,
            },
            inactive_border = "rgba(222222cc)",
        },
    },
})

-- ─── Layout / look (legacy/hyprland.conf, uncommented values only) ─────────
-- gaps 0/0 was explicit there; border_size and rounding were left commented, so
-- they keep Hyprland's defaults (1 and 0) — same as DMS writes on homepc.
hl.config({
    general = {
        gaps_in  = 0,
        gaps_out = 0,
    },
    decoration = {
        dim_special = 0.7,
        blur        = { enabled = false },
    },
    dwindle = {
        force_split          = 2,
        special_scale_factor = 0.8,
    },
    binds = {
        allow_workspace_cycles = true,
    },
    xwayland = {
        force_zero_scaling = true,
    },
    misc = {
        -- legacy/hyprland.conf painted black; hyprland.lua already kills the
        -- default wallpaper/logo/splash for every host.
        background_color = "rgba(0, 0, 0, 1)",
    },
})

-- ─── Input: touchpad + per-device (legacy/dell.conf) ───────────────────────
-- kb_layout=no and kb_options=altwin:swap_lalt_lwin are NOT here — they live in
-- hyprland.lua's hand-owned block and apply to both hosts. The swap means every
-- SUPER bind below is pressed with the PHYSICAL ALT key (physical Win = Alt), which
-- is exactly how the old mainMod = ALT muscle memory maps after the DMS migration.
hl.config({
    input = {
        touchpad = {
            scroll_factor = 0.1, -- legacy/dell.conf: laptop pad is twitchy otherwise
        },
    },
})
hl.device({ name = "dell081c:00-044e:121f-touchpad", natural_scroll = true })
hl.device({ name = "logitech-g-pro--1", sensitivity = -0.7, natural_scroll = true })
hl.device({ name = "logitech-g-pro-wireless-gaming-mouse-2", sensitivity = -0.7, natural_scroll = true })

-- 3-finger horizontal swipe = workspace change (the pad; homepc has the same via DMS)
hl.gesture({ fingers = 3, direction = "horizontal", action = "workspace" })

-- ─── Keybinds ──────────────────────────────────────────────────────────────
-- No DMS on this host: no spotlight/settings/clipboard/powermenu IPC, no DMS bar.
-- Menus are rofi again (scripts live in ~/.config/rofi), the bar is waybar, and
-- locking goes through logind -> hypridle's lock_cmd -> hyprlock
-- (~/.config/hypr/hypridle.conf + hyprlock.conf).
-- Shape mirrors homepc's live set where a plain-Hyprland equivalent exists, so one
-- muscle memory covers both boxes.

-- Terminals / files
hl.bind("SUPER + Return", hl.dsp.exec_cmd("kitty"), { description = "terminal" })
hl.bind("SUPER + CTRL + Return", hl.dsp.exec_cmd("kitty pi"), { description = "kitty running pi" })
hl.bind("SUPER + E", hl.dsp.exec_cmd("nautilus --new-window"), { description = "Files (Nautilus)" })

-- Menus (rofi; legacy $menu / $tabmenu / $emoji)
hl.bind("SUPER + Space", hl.dsp.exec_cmd("rofi -show drun"), { description = "app menu" })
hl.bind("SUPER + Tab", hl.dsp.exec_cmd("rofi -show"), { description = "window/tab menu" })
hl.bind("SUPER + CTRL + Space", hl.dsp.exec_cmd("rofimoji --action clipboard"), { description = "emoji picker" })
hl.bind("SUPER + X", hl.dsp.exec_cmd("~/.config/rofi/powermenu.sh"), { description = "power menu" })
hl.bind("SUPER + SHIFT + P", hl.dsp.exec_cmd("~/.config/rofi/displaymenu_dell.sh"), { description = "display menu (legacy bind)" })

-- Windows
hl.bind("SUPER + Q", hl.dsp.window.close())
hl.bind("SUPER + F", hl.dsp.window.fullscreen({ mode = "maximized", action = "toggle" }))
hl.bind("SUPER + SHIFT + F", hl.dsp.window.fullscreen({ mode = "fullscreen", action = "toggle" }))
hl.bind("SUPER + SHIFT + T", hl.dsp.window.float({ action = "toggle" }), { description = "float (legacy SUPER+V)" })
hl.bind("SUPER + P", hl.dsp.layout("pseudo"), { description = "pseudotile (legacy bind)" })
hl.bind("SUPER + R", hl.dsp.layout("togglesplit"))
hl.bind("SUPER + W", hl.dsp.group.toggle())
hl.bind("SUPER + SHIFT + E", hl.dsp.exit(), { description = "exit Hyprland" })

-- Focus / move
for _, d in ipairs({ { "h", "l" }, { "j", "d" }, { "k", "u" }, { "l", "r" },
                     { "left", "l" }, { "down", "d" }, { "up", "u" }, { "right", "r" } }) do
    hl.bind("SUPER + " .. d[1], hl.dsp.focus({ direction = d[2] }))
    hl.bind("SUPER + SHIFT + " .. d[1], hl.dsp.window.move({ direction = d[2] }))
end
hl.bind("SUPER + CTRL + h", hl.dsp.focus({ monitor = "l" }))
hl.bind("SUPER + CTRL + l", hl.dsp.focus({ monitor = "r" }))
hl.bind("SUPER + SHIFT + CTRL + h", hl.dsp.window.move({ monitor = "l" }))
hl.bind("SUPER + SHIFT + CTRL + l", hl.dsp.window.move({ monitor = "r" }))

-- Workspaces. homepc uses bare SUPER+n / SUPER+SHIFT+n (no resize binds to collide
-- with); the legacy config had the CTRL variants, kept here in the comments only.
for i = 1, 9 do
    hl.bind("SUPER + " .. i, hl.dsp.focus({ workspace = tostring(i) }))
    hl.bind("SUPER + SHIFT + " .. i, hl.dsp.window.move({ workspace = tostring(i) }))
end
hl.bind("SUPER + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind("SUPER + mouse_up", hl.dsp.focus({ workspace = "e-1" }))

-- Scratch (special:magic). Legacy used `code:61` = <AB10> = minus on the `no`
-- layout, which collides with SUPER+minus; SUPER+S is what homepc settled on.
hl.bind("SUPER + S", hl.dsp.workspace.toggle_special("magic"), { description = "toggle scratch" })
hl.bind("SUPER + SHIFT + S", hl.dsp.window.move({ workspace = "special:magic" }), { description = "window -> scratch" })
hl.workspace_rule({ workspace = "special:magic", on_created_empty = "kitty" }) -- legacy on-created-empty

-- Bar. Legacy was `pkill -SIGUSR1 waybar`; waybar runs as a user unit here
-- (programs.waybar in common.nix), so go through systemd.
hl.bind("SUPER + B", hl.dsp.exec_cmd("systemctl restart --user waybar.service"), { description = "reload waybar" })

-- Lock. hypridle's lock_cmd (pidof hyprlock || hyprlock) picks up the logind lock,
-- same key as homepc's DMS lock bind.
hl.bind("SUPER + ALT + L", hl.dsp.exec_cmd("loginctl lock-session"), { description = "lock (hypridle -> hyprlock)" })

-- Audio (pamixer + dunstify; dunst is the notification daemon on this host again)
hl.bind("code:121", hl.dsp.exec_cmd("pamixer -t"), { locked = true, description = "mute" })
hl.bind("code:122", hl.dsp.exec_cmd('pamixer -d 5 && dunstify -h string:x-dunst-stack-tag:audio "Volume: `pamixer --get-volume-human`" -h int:value:"`pamixer --get-volume`"'), { locked = true, repeating = true })
hl.bind("code:123", hl.dsp.exec_cmd('pamixer -i 5 && dunstify -h string:x-dunst-stack-tag:audio "Volume: `pamixer --get-volume-human`" -h int:value:"`pamixer --get-volume`"'), { locked = true, repeating = true })

-- Panel brightness: `light` (programs.light.enable = true in
-- ~/.config/nixos/dell/configuration.nix). The legacy F1-F4 ddcutil binds targeted
-- homepc's external panels and are deliberately not carried over.
hl.bind("code:232", hl.dsp.exec_cmd("light -U 25"), { locked = true, repeating = true, description = "brightness down" })
hl.bind("code:233", hl.dsp.exec_cmd("light -A 25"), { locked = true, repeating = true, description = "brightness up" })

-- Screenshots
hl.bind("SUPER + SHIFT + 4", hl.dsp.exec_cmd("hyprshot -m region"), { description = "region screenshot" })
hl.bind("SUPER + SHIFT + 5", hl.dsp.exec_cmd("hyprshot -m window"), { description = "window screenshot" })

-- Drag / resize with the mouse (legacy bindm)
hl.bind("SUPER + mouse:272", hl.dsp.window.drag(), { mouse = true, description = "move window" })
hl.bind("SUPER + mouse:273", hl.dsp.window.resize(), { mouse = true, description = "resize window" })
